import{_ as e,o as d,c as a,a2 as o}from"./chunks/framework.DA0HUBZR.js";const u=JSON.parse('{"title":"08 · 接口与接口测试基础","description":"","frontmatter":{"title":"08 · 接口与接口测试基础"},"headers":[],"relativePath":"chapters/ch08.md","filePath":"chapters/ch08.md","lastUpdated":1794815418000}'),s={name:"chapters/ch08.md"};function i(n,t,r,l,c,p){return d(),a("div",null,[...t[0]||(t[0]=[o(`<h1 id="第-8-章-·-接口与接口测试基础" tabindex="-1">第 8 章 · 接口与接口测试基础 <a class="header-anchor" href="#第-8-章-·-接口与接口测试基础" aria-label="Permalink to &quot;第 8 章 · 接口与接口测试基础&quot;">​</a></h1><p>接口测试不是「把请求发出去看有没有 200」。它测的是一份<strong>契约</strong>：调用方按约定发什么，服务端就必须按约定回什么，出错时也要按约定报错。</p><p>这一章先把契约拆开看清楚，后面的 AI 生成用例、封装、报告都建立在这上面。</p><h2 id="_1-一份接口契约包含什么" tabindex="-1">1. 一份接口契约包含什么 <a class="header-anchor" href="#_1-一份接口契约包含什么" aria-label="Permalink to &quot;1. 一份接口契约包含什么&quot;">​</a></h2><table tabindex="0"><thead><tr><th>要素</th><th>说明</th><th>测试时关心什么</th></tr></thead><tbody><tr><td>方法与路径</td><td><code>POST /api/users</code></td><td>路径参数拼错、方法不支持（405）</td></tr><tr><td>参数位置</td><td>query / path / header / body / form / cookie</td><td>放错位置服务端收不到</td></tr><tr><td>参数约束</td><td>必填、类型、长度、范围、枚举</td><td>缺失、越界、类型错（422）</td></tr><tr><td>鉴权</td><td>Bearer / Cookie / 签名</td><td>无 token、过期 token、越权（401 / 403）</td></tr><tr><td>成功响应</td><td>状态码 + 结构 + 字段类型</td><td>结构变了前端就崩</td></tr><tr><td>失败响应</td><td>状态码 + 错误码 + message</td><td>报错要说清是哪一项错了</td></tr><tr><td>副作用</td><td>创建、扣款、发消息</td><td>重复提交会不会重复扣（幂等）</td></tr></tbody></table><p>一份能测的文档，至少要有上表全部内容。缺哪一项，就在用例里标「待澄清」——这和需求分析时的「待澄清项」是同一件事。</p><h2 id="_2-一次请求长什么样" tabindex="-1">2. 一次请求长什么样 <a class="header-anchor" href="#_2-一次请求长什么样" aria-label="Permalink to &quot;2. 一次请求长什么样&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>POST /api/orders HTTP/1.1</span></span>
<span class="line"><span>Host: 127.0.0.1:8010</span></span>
<span class="line"><span>Authorization: Bearer 2f9c...</span></span>
<span class="line"><span>Content-Type: application/json</span></span>
<span class="line"><span>Idempotency-Key: order-20261116-001</span></span>
<span class="line"><span></span></span>
<span class="line"><span>{&quot;items&quot;:[{&quot;sku&quot;:&quot;A-1&quot;,&quot;qty&quot;:2}]}</span></span></code></pre></div><p>响应：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>HTTP/1.1 201 Created</span></span>
<span class="line"><span>Content-Type: application/json</span></span>
<span class="line"><span>Location: /api/orders/1</span></span>
<span class="line"><span></span></span>
<span class="line"><span>{&quot;id&quot;:1,&quot;user&quot;:&quot;alice&quot;,&quot;amount&quot;:20,&quot;status&quot;:&quot;created&quot;}</span></span></code></pre></div><p><code>requests</code> 把这些细节都封装了，但<strong>测试时必须知道每个字段落在哪</strong>——尤其是 <code>Authorization</code>、<code>Content-Type</code>、<code>Idempotency-Key</code> 这类决定行为的头。</p><h2 id="_3-方法与幂等性" tabindex="-1">3. 方法与幂等性 <a class="header-anchor" href="#_3-方法与幂等性" aria-label="Permalink to &quot;3. 方法与幂等性&quot;">​</a></h2><table tabindex="0"><thead><tr><th>方法</th><th>语义</th><th>幂等</th><th>常见误用</th></tr></thead><tbody><tr><td>GET</td><td>查询</td><td>是</td><td>用 GET 做删除，被浏览器预取</td></tr><tr><td>POST</td><td>创建 / 动作</td><td><strong>否</strong></td><td>重复点击生成两笔订单</td></tr><tr><td>PUT</td><td>整体替换</td><td>是</td><td>只传部分字段，把其余字段清空</td></tr><tr><td>PATCH</td><td>局部更新</td><td>通常否</td><td>并发下互相覆盖</td></tr><tr><td>DELETE</td><td>删除</td><td>是</td><td>删除不存在的资源返回 500</td></tr></tbody></table><p>「幂等」是可测的：同一个请求发两次，资源数量不应变化。第 13 章会用 <code>Idempotency-Key</code> 专门验它。</p><h2 id="_4-状态码-先看分组-再看具体" tabindex="-1">4. 状态码：先看分组，再看具体 <a class="header-anchor" href="#_4-状态码-先看分组-再看具体" aria-label="Permalink to &quot;4. 状态码：先看分组，再看具体&quot;">​</a></h2><table tabindex="0"><thead><tr><th>分组</th><th>含义</th><th>测试里怎么用</th></tr></thead><tbody><tr><td>2xx</td><td>成功</td><td>201 要带 <code>Location</code>；204 不能有 body</td></tr><tr><td>3xx</td><td>重定向</td><td>接口一般不跟随，<code>allow_redirects=False</code> 看真实响应</td></tr><tr><td>4xx</td><td>调用方问题</td><td>400 参数格式错、401 未认证、403 无权限、404 不存在、409 冲突、422 语义校验失败、429 限流</td></tr><tr><td>5xx</td><td>服务端问题</td><td>500 未捕获异常、502 上游错、503 过载、504 超时</td></tr></tbody></table><p>三个最容易混的：</p><ul><li><strong>401 vs 403</strong>：401 是「你是谁我不知道」，403 是「知道你是谁，但你不能做」。</li><li><strong>400 vs 422</strong>：400 通常指报文本身坏了（不是 JSON），422 指报文能解析但字段不合法。</li><li><strong>409 vs 422</strong>：409 是「和现有状态冲突」（重名、已支付），422 是「这一条数据本身不合法」。</li></ul><p>断言时<strong>不要只断言 <code>status_code == 200</code></strong>，要断言到「哪个字段、哪种错误」。</p><h2 id="_5-参数该放哪" tabindex="-1">5. 参数该放哪 <a class="header-anchor" href="#_5-参数该放哪" aria-label="Permalink to &quot;5. 参数该放哪&quot;">​</a></h2><table tabindex="0"><thead><tr><th>位置</th><th>适合放</th><th>例子</th></tr></thead><tbody><tr><td>query</td><td>筛选、分页、排序</td><td><code>?page=1&amp;size=20</code></td></tr><tr><td>path</td><td>资源标识</td><td><code>/api/users/42</code></td></tr><tr><td>body(JSON)</td><td>结构化数据</td><td><code>{&quot;name&quot;:&quot;dave&quot;}</code></td></tr><tr><td>form</td><td>表单提交、文件上传</td><td><code>multipart/form-data</code></td></tr><tr><td>header</td><td>鉴权、幂等键、追踪号</td><td><code>Authorization</code>、<code>Idempotency-Key</code>、<code>X-Request-Id</code></td></tr><tr><td>cookie</td><td>会话</td><td><code>SESSIONID=...</code></td></tr></tbody></table><p>同一个值放错位置，服务端就收不到；这类 bug 在手工测试里极常见，所以用例要覆盖「必填参数缺失」和「参数放错位置」。</p><h2 id="_6-鉴权-四种形态与测试点" tabindex="-1">6. 鉴权：四种形态与测试点 <a class="header-anchor" href="#_6-鉴权-四种形态与测试点" aria-label="Permalink to &quot;6. 鉴权：四种形态与测试点&quot;">​</a></h2><table tabindex="0"><thead><tr><th>形态</th><th>长什么样</th><th>测试点</th></tr></thead><tbody><tr><td>Basic</td><td><code>Authorization: Basic base64(user:pass)</code></td><td>口令错、未编码</td></tr><tr><td>Bearer</td><td><code>Authorization: Bearer &lt;token&gt;</code></td><td>无 token、过期、签名被改</td></tr><tr><td>Cookie</td><td><code>Cookie: SESSIONID=...</code></td><td>会话固定、退出后是否失效</td></tr><tr><td>签名</td><td><code>X-Sign: md5(params+secret)</code></td><td>参数改一个字节签名是否失效</td></tr></tbody></table><p>本章的 SUT 用 Bearer，token 有 1 小时有效期。写用例时，<strong>「无 token 返回 401」和「过期 token 返回 401」要分开测</strong>——实现里经常只判了前者。</p><h2 id="_7-没有文档怎么办-抓包" tabindex="-1">7. 没有文档怎么办：抓包 <a class="header-anchor" href="#_7-没有文档怎么办-抓包" aria-label="Permalink to &quot;7. 没有文档怎么办：抓包&quot;">​</a></h2><ol><li>打开开发者工具 → Network → 勾选 <code>Preserve log</code>（防跳转丢失）。</li><li>触发一次操作，找到目标请求（按 URL 关键词过滤）。</li><li>看四处：<code>Request Method</code> + <code>Request URL</code>、<code>Request Headers</code>（尤其 <code>Authorization</code>、<code>Content-Type</code>）、<code>Payload</code>、<code>Response</code>。</li><li>右键 → <code>Copy as cURL</code>，可以直接改成 <code>requests</code> 代码。</li></ol><p>Fiddler / Charles 的用处是「浏览器抓不到的请求」（App、HTTPS 双向认证场景）。</p><h2 id="_8-接口测试的九个检查维度" tabindex="-1">8. 接口测试的九个检查维度 <a class="header-anchor" href="#_8-接口测试的九个检查维度" aria-label="Permalink to &quot;8. 接口测试的九个检查维度&quot;">​</a></h2><p>拿到一个接口，按这张表过一遍，用例就不会漏：</p><ol><li><strong>正常流</strong>：合法参数 → 期望状态码 + 关键字段。</li><li><strong>必填缺失</strong>：逐个删必填字段。</li><li><strong>类型/格式</strong>：数字传字符串、日期格式错、超长字符串。</li><li><strong>边界</strong>：分页 <code>size=0/1/100/101</code>，金额 0 / 0.01 / 上限。</li><li><strong>业务规则</strong>：重名、状态机非法流转（已支付再支付）。</li><li><strong>鉴权与越权</strong>：无 token、他人资源、低权限角色。</li><li><strong>幂等与并发</strong>：重复提交、同一秒两次请求。</li><li><strong>错误信息质量</strong>：报错是否指明字段，是否泄漏堆栈。</li><li><strong>兼容与性能</strong>：字段新增是否破坏老客户端、P95 延迟。</li></ol><h2 id="_9-本章实操" tabindex="-1">9. 本章实操 <a class="header-anchor" href="#_9-本章实操" aria-label="Permalink to &quot;9. 本章实操&quot;">​</a></h2><p><code>labs/ch08-http-basics/</code>：起一个只用标准库写的 SUT，用 <code>requests</code> 把上面九个维度里的六项真跑一遍。</p><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.venv\\Scripts\\</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">python.exe</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> labs\\ch08</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">http</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">basics\\explore_api.py</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.venv\\Scripts\\</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">python.exe</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> -</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">m pytest labs\\ch08</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">http</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">basics </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">q</span></span></code></pre></div><p>实验里会看到：401、404、409、422 分别长什么样，<code>Location</code> 头怎么用，以及「同一个 POST 发两次」为什么必须靠 <code>Idempotency-Key</code> 才安全。</p><h2 id="_10-自测" tabindex="-1">10. 自测 <a class="header-anchor" href="#_10-自测" aria-label="Permalink to &quot;10. 自测&quot;">​</a></h2><ol><li>401 和 403 的区别是什么？各举一个真实场景。</li><li>为什么 <code>PUT</code> 只传部分字段是危险操作？</li><li>一个创建接口返回 200 而不是 201，算 bug 吗？怎么判断？</li><li>接口返回 <code>{&quot;code&quot;:0,&quot;msg&quot;:&quot;ok&quot;,&quot;data&quot;:null}</code>，<code>data</code> 为空时前端崩了——这算接口问题还是前端问题？</li><li>用 F12 抓一个带 token 的请求，说明 token 放在哪、怎么拼进 <code>requests</code>。</li></ol><h2 id="附-自测答案" tabindex="-1">附：自测答案 <a class="header-anchor" href="#附-自测答案" aria-label="Permalink to &quot;附：自测答案&quot;">​</a></h2><ol><li>401 是「没认证」：没带 token、token 过期、签名错误；403 是「认证过了但没权限」：普通用户访问管理接口。真实场景：token 过期返回 401，普通账号调 <code>/admin/users</code> 返回 403。</li><li><code>PUT</code> 语义是「整体替换」，只传部分字段意味着其他字段被置空或删除——这是数据丢失级别的操作。只想改一两个字段用 <code>PATCH</code>。</li><li>不一定算 bug，先看契约：按 REST 惯例创建资源应返回 201 并带 <code>Location</code>；如果接口文档就写 200，那按文档断言，但要在评审里提出来，因为这会影响客户端缓存和幂等设计。</li><li>算接口契约问题，前端也有责任。接口应明确「空集合返回 <code>[]</code>、无对象返回 <code>null</code>」，并在文档写死；前端不能假设 <code>data</code> 一定有内容。两边都要修，接口先定契约。</li><li>token 通常在请求头 <code>Authorization: Bearer &lt;token&gt;</code>。抓包看 Request Headers，复制到代码里：<code>headers = {&quot;Authorization&quot;: f&quot;Bearer {token}&quot;}</code>，别把 token 写死在代码里，从登录响应或环境变量取。</li></ol><h2 id="学生常问" tabindex="-1">学生常问 <a class="header-anchor" href="#学生常问" aria-label="Permalink to &quot;学生常问&quot;">​</a></h2><p><strong>Q：接口测试要不要连真实数据库校验？</strong></p><p>A：看目标。验证「接口返回对不对」只看响应就够；验证「数据真的落库了」要查库或再调一次查询接口。优先用查询接口验证，直连数据库的成本高、还会把测试绑死在表结构上。</p><p><strong>Q：<code>200</code> 但业务失败，这种接口怎么测？</strong></p><p>A：看响应体里的业务码或状态字段，断言业务码而不是 HTTP 码。这类接口要在用例里明确写「HTTP 200 + code=1001」两个断言，否则只断言 200 会一直绿。</p><p><strong>Q：怎么测幂等？</strong></p><p>A：同一个幂等键连续提交两次，断言第二次返回 200（不是 201）、且数据库只有一条记录、响应体里的 id 相同。没有幂等键的接口，测「重复提交会被拒绝（409）」。</p><h2 id="面试题" tabindex="-1">面试题 <a class="header-anchor" href="#面试题" aria-label="Permalink to &quot;面试题&quot;">​</a></h2><p><strong>Q：一个接口的测试点你会从哪几个维度拆？</strong></p><p>A：功能（正常/异常/边界）、参数（必填、类型、长度、枚举、位置）、鉴权（无 token、过期、越权）、状态（重复提交、并发、状态机非法流转）、数据（分页边界、大数据量、特殊字符）、协议（方法、Content-Type、状态码、响应头）、性能与兼容。</p><p><strong>Q：HTTP 和 HTTPS 在测试上有什么区别？</strong></p><p>A：HTTPS 多了 TLS 握手，测试要关注证书有效性、过期、域名不匹配、协议版本；抓包需要装证书或用代理；接口本身的行为应该和 HTTP 一致，出现差异通常是中间层（网关、WAF）造成的。</p><p><strong>Q：为什么说「接口测试比 UI 测试更划算」？</strong></p><p>A：接口层没有渲染和等待，执行快、稳定、定位准，一个 bug 在接口层暴露的成本远低于 UI 层；UI 用例只保留关键主流程，其余下沉到接口层。</p><h2 id="延伸知识" tabindex="-1">延伸知识 <a class="header-anchor" href="#延伸知识" aria-label="Permalink to &quot;延伸知识&quot;">​</a></h2><ul><li><code>Content-Type</code> 决定服务端怎么解析 body：<code>application/json</code>、<code>application/x-www-form-urlencoded</code>、<code>multipart/form-data</code> 三种最常见，传错就是 415 或参数收不到。</li><li>状态码只是约定，真正的契约在文档里：同一个 422，有的项目表示参数错，有的表示业务规则不满足。</li><li>分页要测三处：第 1 页、最后一页、越界页（返回空列表而不是报错）。</li><li>时间字段统一用 ISO 8601 带时区，跨时区比较才不会错。</li></ul>`,55)])])}const k=e(s,[["render",i]]);export{u as __pageData,k as default};
